"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  useRef,
} from "react";

import { ThemeAccessSync } from "@/components/theme";
import { useRouter } from "next/navigation";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import type { ClientEntitlements } from "@/lib/entitlements";
import type { QuotaSnapshot } from "@/lib/quota-snapshot";

import { EMPTY_ROLE_USAGE, type RoleUsage } from "@/lib/roles";

const QuotaContext = createContext<{
  quota: QuotaSnapshot;
  entitlements: ClientEntitlements;
  roleUsage: RoleUsage;
  update: (quota: QuotaSnapshot) => void;
} | null>(null);

export function WorkspaceQuotaProvider({
  quota,
  entitlements,
  roleUsage = EMPTY_ROLE_USAGE,
  children,
}: {
  quota: QuotaSnapshot;
  entitlements: ClientEntitlements;
  roleUsage?: RoleUsage;
  children: React.ReactNode;
}) {
  const router = useRouter();
  const [snapshot, setSnapshot] = useState({ source: quota, quota });
  if (snapshot.source !== quota) setSnapshot({ source: quota, quota });
  const version = useRef(quota.accessVersion);
  const update = useCallback(
    (value: QuotaSnapshot) => {
      if (value.accessVersion && value.accessVersion !== version.current) {
        version.current = value.accessVersion;
        router.refresh();
      }
      setSnapshot((current) =>
        JSON.stringify(current.quota) === JSON.stringify(value)
          ? current
          : { ...current, quota: value },
      );
    },
    [router],
  );
  const initialMode = quota.mode;
  useEffect(() => {
    let active = true,
      pending = false;
    const controller = new AbortController();
    async function refresh() {
      if (document.visibilityState !== "visible" || pending) return;
      pending = true;
      try {
        const response = await fetch("/api/quota", {
          cache: "no-store",
          signal: controller.signal,
        });
        if (!response.ok) return;
        const result = await response.json();
        if ((result.mode === "gated" ? "gated" : "legacy") !== initialMode)
          router.refresh();
        if (
          active &&
          Number.isInteger(result.used) &&
          result.used >= 0 &&
          Number.isInteger(result.limit)
        ) {
          if (result.mode === "gated" && result.daily && result.monthly)
            update(result as QuotaSnapshot);
          else if (result.limit === DAILY_EMAIL_LIMIT)
            update({
              accessVersion: result.accessVersion,
              notices: result.notices,
              mode: "legacy",
              used: result.used,
              limit: DAILY_EMAIL_LIMIT,
            });
        }
      } catch {
        /* Keep the last confirmed snapshot until the next successful lookup. */
      } finally {
        pending = false;
      }
    }
    const onReturn = () => void refresh();
    const onAccessRefresh = () => {
      // Entitlements also govern Premium features when quota gating is off.
      // Refresh them even if a quota poll is already pending or unavailable.
      router.refresh();
      void refresh();
    };
    const interval = window.setInterval(onReturn, 60000);
    window.addEventListener("focus", onReturn);
    window.addEventListener("mailloop:access-refresh", onAccessRefresh);
    document.addEventListener("visibilitychange", onReturn);
    return () => {
      active = false;
      controller.abort();
      window.clearInterval(interval);
      window.removeEventListener("focus", onReturn);
      window.removeEventListener("mailloop:access-refresh", onAccessRefresh);
      document.removeEventListener("visibilitychange", onReturn);
    };
  }, [update, initialMode, router]);
  const deadline =
    snapshot.quota.mode === "gated"
      ? snapshot.quota.entitlements.accessDeadline
      : entitlements.accessDeadline;
  useEffect(() => {
    if (!deadline) return;
    let timer: number;
    function schedule() {
      const delay = Math.max(0, Date.parse(deadline!) - Date.now() + 25);
      timer = window.setTimeout(
        () => {
          if (Date.parse(deadline!) > Date.now()) schedule();
          else refreshWorkspaceAccess();
        },
        Math.min(delay, 2147483647),
      );
    }
    schedule();
    return () => window.clearTimeout(timer);
  }, [deadline]);
  return (
    <QuotaContext
      value={{
        quota: snapshot.quota,
        roleUsage,
        entitlements:
          snapshot.quota.mode === "gated"
            ? snapshot.quota.entitlements
            : entitlements,
        update,
      }}
    >
      <ThemeAccessSync
        allowed={
          (snapshot.quota.mode === "gated"
            ? snapshot.quota.entitlements
            : entitlements
          ).features.blackThemes
        }
        deadline={deadline}
      />
      {children}
    </QuotaContext>
  );
}

export function useWorkspaceQuota(source?: QuotaSnapshot) {
  const context = useContext(QuotaContext);
  if (!context) throw new Error("Workspace quota requires its provider.");
  const { quota, update } = context;
  useEffect(() => {
    if (source !== undefined) update(source);
  }, [source, update]);
  return quota;
}

export function WorkspaceQuotaStatus() {
  const quota = useWorkspaceQuota();
  return (
    <span className="text-xs text-body">
      {quota.mode === "gated"
        ? !quota.sendingAllowed
          ? `${quota.plan === "PAID" ? "Paid" : "Free"} · Sending paused`
          : `${quota.plan === "PAID" ? "Paid" : "Free"} · ${quota.daily.remaining} daily · ${quota.monthly.remaining} monthly remaining`
        : `${quota.used} / ${quota.limit} used or queued`}
    </span>
  );
}

export function WorkspaceCapacity({ source }: { source?: QuotaSnapshot }) {
  const quota = useWorkspaceQuota(source);
  return (
    <p aria-label="Sending capacity" className="text-xs leading-5 text-body">
      {quota.mode === "gated"
        ? !quota.sendingAllowed
          ? "Sending paused."
          : `${quota.daily.remaining} daily · ${quota.monthly.startsAt ? `${quota.monthly.remaining} monthly remaining` : "monthly allowance unavailable"}`
        : `${Math.max(0, quota.limit - quota.used)} remaining per rolling 24 hours`}
    </p>
  );
}

export function useWorkspaceEntitlements() {
  const context = useContext(QuotaContext);
  if (!context)
    throw new Error("Workspace entitlements require their provider.");
  return context.entitlements;
}
export function refreshWorkspaceAccess() {
  window.dispatchEvent(new Event("mailloop:access-refresh"));
}

export function useWorkspaceRoleUsage() {
  const context = useContext(QuotaContext);
  if (!context) throw new Error("Workspace roles require their provider.");
  return context.roleUsage;
}
